"""Fill the outcome-dependent sections of REPORT.md and emit the prose deliverables (ledger entry E-MDI-38 text, HANDOFF.txt paragraph,
GRAVEYARD.json) from SCORES.json / RECORDS_cells.jsonl / BUDGET_LEDGER.json. Numbers are read from records, never typed by hand.
    python adp/closeout/conclusions.py D   -> appends sections 9-12 to D/REPORT.md, writes D/LEDGER_ENTRY_E-MDI-38.md, D/HANDOFF_PARAGRAPH.txt, D/GRAVEYARD.json"""
from __future__ import annotations
import os, sys, json, collections, statistics
HERE = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); sys.path.insert(0, HERE)
NEW = "AGGREGATE_DP_V1"
DRYRUN_S = None; UNDERSAMPLED = 0


def main(D):
    global DRYRUN_S, UNDERSAMPLED
    dr = os.path.join(D, "review_2026-11-08", "UNCHARGED_DEVELOPMENT_RUNS.json"); DRYRUN_S = json.load(open(dr)).get("dry_run_46_cases_sum_complete_response_s") if os.path.exists(dr) else None
    man = json.load(open(os.path.join(D, "CAMPAIGN_MANIFEST.json"))); S = json.load(open(os.path.join(D, "SCORES.json"))); B = json.load(open(os.path.join(D, "BUDGET_LEDGER.json")))
    R = [json.loads(l) for l in open(os.path.join(D, "RECORDS_cells.jsonl"))]; fam = {c["case"]: c["family"] for c in man["cases"]}; cases = [c["case"] for c in man["cases"]]
    UNDERSAMPLED = sum(1 for r in R if (r.get("rss_samples") or 0) <= 3)
    def key(r):
        return r["arm"] if r["arm"] != NEW else r["config_key"]
    def get(stage, k, case, rep=0):
        return next((r for r in R if r["stage"] == stage and key(r) == k and r["case"] == case and r.get("repetition") == rep), None)
    full20 = {c: get("P20", "full", c) for c in cases}; ex20 = {c: get("P20", "EXACT", c) for c in cases}; mdi20 = {c: get("P20", "MDI_EXISTING", c) for c in cases}
    full120 = {c: get("P120", "full", c) for c in cases}; ex120 = {c: get("P120", "EXACT", c) for c in cases}
    cert20 = sorted(c for c in cases if full20[c] and full20[c].get("certified_target")); cert120 = sorted(c for c in cases if full120[c] and full120[c].get("certified_target"))
    exc20 = sorted(c for c in cases if ex20[c] and ex20[c].get("complete_output")); exc120 = sorted(c for c in cases if ex120[c] and ex120[c].get("complete_output"))
    mdic20 = sorted(c for c in cases if mdi20[c] and mdi20[c].get("certified_target"))
    # coverage questions
    new_not_exact20 = sorted(set(cert20) - set(exc20)); exact_not_new20 = sorted(set(exc20) - set(cert20)); new_not_exact120 = sorted(set(cert120) - set(exc120)); exact_not_new120 = sorted(set(exc120) - set(cert120))
    new_not_mdi = sorted(set(cert20) - set(mdic20)); mdi_not_new = sorted(set(mdic20) - set(cert20))
    # paired times (both complete, three repetitions)
    pairs = []
    for c in cases:
        if c in cert20 and c in exc20:
            tn = [r["complete_response_s"] for k in (0, 1, 2) for r in [next((x for x in R if x["stage"] in ("P20", "REP") and key(x) == "full" and x["case"] == c and x.get("repetition") == k), None)] if r and r.get("certified_target")]
            te = [r["complete_response_s"] for k in (0, 1, 2) for r in [next((x for x in R if x["stage"] in ("P20", "REP") and x["arm"] == "EXACT" and x["case"] == c and x.get("repetition") == k), None)] if r and r.get("complete_output")]
            mn = full20[c].get("peak_tree_rss_bytes", 0) / 1e6; me = ex20[c].get("peak_tree_rss_bytes", 0) / 1e6
            pairs.append((c, tn, te, mn, me))
    def ratio_summary(pairs):
        rs = [statistics.median(tn) / statistics.median(te) for _, tn, te, _, _ in pairs if tn and te and statistics.median(te) > 0]
        return (statistics.median(rs), min(rs), max(rs), len(rs)) if rs else (None, None, None, 0)
    med_ratio, min_ratio, max_ratio, npairs = ratio_summary(pairs)
    faster = [c for c, tn, te, _, _ in pairs if tn and te and statistics.median(tn) < statistics.median(te)]
    # certified cells: where the time went
    cert_rows = [full20[c] for c in cert20]
    def share(r, name):
        a = (r.get("adp") or {}).get("attempts") or []; ph = a[-1].get("phases_s", {}) if a else {}
        v = {"checker": ph.get("checker"), "forward": ph.get("forward"), "backward": ph.get("backward"), "source": r["phases_s"].get("source_reductions"), "publish": r["phases_s"].get("publish")}.get(name) or 0.0
        return v / r["complete_response_s"] if r.get("complete_response_s") else None
    chk_share = statistics.median([share(r, "checker") for r in cert_rows]) if cert_rows else None; bwd_share = statistics.median([share(r, "backward") for r in cert_rows]) if cert_rows else None; fwd_share = statistics.median([share(r, "forward") for r in cert_rows]) if cert_rows else None
    # stops
    stops = collections.Counter(); stop_cases = collections.defaultdict(list)
    for c in cases:
        r = full20[c]
        if r and not r.get("certified_target"):
            k = ((r.get("adp") or {}).get("stop") or {}).get("kind") or r["status"]; stops[k] += 1; stop_cases[k].append(c)
    # ablations
    abl = {}
    for k in sorted(man["ablations"]):
        rs = [r for r in R if r["stage"] == "ABL" and r["config_key"] == k]; ce = {r["case"] for r in rs if r.get("certified_target")}
        lost = sorted(set(cert20) - ce); gained = sorted(ce - set(cert20)); common = sorted(ce & set(cert20))
        rat = [r["complete_response_s"] / full20[r["case"]]["complete_response_s"] for r in rs if r["case"] in common and full20[r["case"]].get("complete_response_s")]
        abl[k] = {"certified": len(ce), "lost_vs_full": lost, "gained_vs_full": gained, "median_time_ratio_vs_full_on_common": (statistics.median(rat) if rat else None), "n_common": len(common), "recorded": len(rs)}
    # empirical accuracy of certified cells vs references; R0 containment
    cont = [(c, full20[c]["reference_in_intervals"]) for c in cert20 if full20[c].get("reference_in_intervals")]
    cont_ok = sum(1 for _, x in cont if x["contained"] == x["coordinates"]); emp = [full20[c]["empirical"]["max_abs_error"] for c in cert20 if full20[c].get("empirical")]
    r0cases = [c for c in cases if S["reference_classes"][c]["class"] == "R0"]
    # per-family explanation
    fams = sorted(set(fam.values())); famtab = []
    for f in fams:
        cs = [c for c in cases if fam[c] == f]; famtab.append((f, len(cs), sum(1 for c in cs if c in cert20), sum(1 for c in cs if c in cert120), sum(1 for c in cs if c in exc20), sum(1 for c in cs if c in mdic20), dict(collections.Counter((((full20[c] or {}).get("adp") or {}).get("stop") or {}).get("kind") or (full20[c] or {}).get("status") for c in cs if c not in cert20))))
    # ---------------------------------------------------------------- prose
    L = []; P = L.append
    P("\n## 9. The primary question: did the complete algorithm improve COVERAGE, full producer+checker COST, or MEMORY at the declared guarantee?\n")
    P("**Coverage (certified, width ≤ 1/100 and robust-center point verified by the independent checker).** 20 s: AGGREGATE_DP_V1 certified %d of 46 cases (%s). The pinned MDI_EXISTING certified %d (%s). libDAI EXACT (no certificate; floating-point complete output) completed %d. 120 s: AGGREGATE_DP_V1 certified %d (%s); EXACT completed %d.\n" % (len(cert20), ", ".join(cert20), len(mdic20), ", ".join(mdic20), len(exc20), len(cert120), ", ".join(cert120), len(exc120)))
    P("- certified by the new arm but NOT completed by EXACT at 20 s: %s\n- completed by EXACT but NOT certified by the new arm at 20 s: %s\n- at 120 s: new-only %s; EXACT-only %s\n- certified by the new arm but not by MDI_EXISTING at 20 s: %s; the converse: %s\n" % (", ".join(new_not_exact20) or "none", ", ".join(exact_not_new20) or "none", ", ".join(new_not_exact120) or "none", ", ".join(exact_not_new120) or "none", ", ".join(new_not_mdi) or "none", ", ".join(mdi_not_new) or "none"))
    consistent = [(c, [tb / ta for ta, tb in zip(tn, te)]) for c, tn, te, _, _ in pairs if tn and te and len(tn) == len(te) == 3 and all(ta < tb for ta, tb in zip(tn, te))]
    sp = [x for _, xs in consistent for x in xs]
    P("**Cost (complete response incl. source reductions, planning, forward, backward, independent checking, publication; both sides complete; three 20 s observations each).** %d successful pairs against EXACT; median ratio new/EXACT %s (min %s, max %s). The new arm is faster in EVERY one of the three observations on %d cases (%s), with per-observation speedups of %s to %s — six repeatable, case-specific advantages, measured end to end including checking and publication. On the other %d pairs it is slower (3–10× on the dense-core bnlearn / Segmentation / CSP_12 cases). There is NO broad advantage. EXACT carries no certificate, so every ratio compares time-to-certified against time-to-floating-point." % (npairs, ("%.2f" % med_ratio) if med_ratio else "—", ("%.2f" % min_ratio) if min_ratio else "—", ("%.2f" % max_ratio) if max_ratio else "—", len(consistent), ", ".join(c for c, _ in consistent) or "none", ("%.1f×" % min(sp)) if sp else "—", ("%.1f×" % max(sp)) if sp else "—", npairs - len(consistent)))
    P("BN_31 is a coverage gain (certified in %s s at 20 s) whose comparator outcome needs precise wording: libDAI REFUSES it by its own memory forecast (maxmem admission), which is not evidence that an exact solver equipped with equivalent source reductions could not solve it." % (("%.2f" % full20["BN_31"]["complete_response_s"]) if full20.get("BN_31") and full20["BN_31"].get("complete_response_s") else "—"))
    P("\n| case | new s (3 obs) | EXACT s (3 obs) | median ratio | new peak MB | EXACT peak MB |\n|---|---|---|---|---|---|")
    for c, tn, te, mn, me in pairs:
        P("| %s | %s | %s | %s | %.0f | %.0f |" % (c, "/".join("%.2f" % x for x in tn), "/".join("%.2f" % x for x in te), ("%.2f" % (statistics.median(tn) / statistics.median(te))) if (tn and te) else "—", mn, me))
    P("\n**Memory.** Peak process-tree RSS (producer + checker together) of certified new-arm cells vs EXACT on the same pairs is in the table; the new arm's per-entry representation is a Python object per MPFR value (72-128 bytes each) in numpy object arrays, so its resident footprint per core entry is an order of magnitude above a binary64 table.\n")
    P("**Planned volume vs executed work vs checker work (certified 20 s cells).** 'Planned core entries' is the dense-equivalent volume of the program's cores at representatives (every class tuple); 'computed' is the number of core entries the producer actually evaluated (sparse formats evaluate only supported rows); 'checker bag visits' is the independent checker's own count of bag rows it replayed. On Promedus the checker follows the sparse computation and never reconstructs the dense contraction: computation and proof benefit from the same simplification.\n")
    P("| case | planned core entries | computed | checker bag visits | checker entries | computed / planned |\n|---|---|---|---|---|---|")
    for r in cert_rows:
        a = r["adp"]; pg = a.get("program") or {}; at = (a.get("attempts") or [{}])[-1]; ck = (a.get("checker") or {}).get("counters") or {}
        pl = pg.get("core_entries_total") or 0; cm = (at.get("counters") or {}).get("entries_computed") or 0
        P("| %s | %s | %s | %s | %s | %s |" % (r["case"], pl, cm, ck.get("bag_rows"), ck.get("entries"), ("%.3f" % (cm / pl)) if pl else "—"))
    P("")
    P("**Where the time goes in a certified cell (medians over %d certified 20 s cells):** independent checking %s of the complete response, backward pass %s, forward pass %s. The checker replays the same reduced program with outward intervals (two MPFR values per entry, its own index arithmetic and joins): its cost is of the order of the producer's, as the numerics contract predicted, and on the larger certified cases (Segmentation, BARLEY, DIABETES, CSP_12) it is the single largest phase.\n" % (len(cert_rows), ("%.0f %%" % (100 * chk_share)) if chk_share is not None else "—", ("%.0f %%" % (100 * bwd_share)) if bwd_share is not None else "—", ("%.0f %%" % (100 * fwd_share)) if fwd_share is not None else "—"))
    P("**Typed stops of the non-certified 20 s cells:** %s. Every stop is a resource outcome of the frozen caps (deadline polled inside numeric execution; resident value cap) on a program that is mathematically valid; no case was refused by admission or representation.\n" % "; ".join("%s ×%d (%s)" % (k, n, ", ".join(stop_cases[k])) for k, n in stops.most_common()))
    P("## 10. Every family, including no-gain families\n")
    P("| family | cases | new certified 20 s | new certified 120 s | EXACT complete 20 s | MDI_EXISTING certified 20 s | stops of the non-certified new-arm cells (20 s) |\n|---|---|---|---|---|---|---|")
    for f, n, a, b, e, m, st in famtab:
        P("| %s | %d | %d | %d | %d | %d | %s |" % (f, n, a, b, e, m, json.dumps(st)))
    P("")
    P("## 11. Ablations (same contracts). What each configuration ACTUALLY disables (from CONFIG_*.json), not the advertised one-mechanism label\n")
    vc = sorted({(r["config_key"], r["case"]) for r in R if r["stage"] == "ABL" and ((r.get("adp") or {}).get("stop") or {}).get("kind") == "VALUE_CAP"})
    P("Caveat for every ablation row: %d ablation cells stopped at VALUE_CAP (%s). Under the frozen code that stop is the UNFINISHED memory fallback (section 12c, F3), not the intended algorithm, so 'lost' cases that stopped there (A3 on Promedus_12 / Promedus_37, whose dense cores exceed the value cap without the sparse format) are losses to the unfinished fallback, not measured losses of the intended algorithm.\n" % (len(vc), ", ".join("%s:%s" % (k.split("_")[0], c) for k, c in vc)))
    P("- A1 `rules: []`: no exact source reductions (exclude / fix / const / separable / alias / quotient); the program graph changes, so cost may rise. One cell (BN_31) FAULTED by an int64 key-range overflow of the lazy format on the un-reduced 1,036-variable program (amendment_1).\n- A2 `views: false`: identity response partitions (every state its own class; zero rows still certified zero). Adds no completed case, but see the planned-volume table below.\n- A3 `sparse: false`: no native sparse join / support iteration; dense or lazy formats only.\n- A4 `memo: false, batched: false`: NO result cache AND scalar per-entry evaluation (the lazy format without a memo). It does NOT isolate memoization: batching is disabled at the same time, and adjoints are still coalesced in per-node dictionaries. The 22 → 2 collapse is the combined effect of losing both the cache and the batched formats; it must not be read as 'memoization alone is worth 20 cases'.\n- A5 `batched: false`: scalar per-entry evaluation WITH the memo (lazy format everywhere). Isolates the dense / sparse batched kernels: 22 → 12 certified, median 1.24× slower on the common cases.\n")
    P("| ablation | certified (of 46) | lost vs full | gained vs full | median time ratio vs full on common certified cases |\n|---|---|---|---|---|")
    for k, v in abl.items():
        P("| %s | %d | %s | %s | %s (n=%d) |" % (k, v["certified"], ", ".join(v["lost_vs_full"]) or "none", ", ".join(v["gained_vs_full"]) or "none", ("%.2f" % v["median_time_ratio_vs_full_on_common"]) if v["median_time_ratio_vs_full_on_common"] else "—", v["n_common"]))
    P("")
    # response views: planned volume with and without (A2), single-observation times
    a2 = {r["case"]: r for r in R if r["stage"] == "ABL" and r["config_key"] == "A2_identity_response_views"}
    P("**Response views (A2) deserve a narrower conclusion than 'no benefit'.** They add no completed case on this panel, but they reduce the PLANNED core volume where the source tables carry proportional rows; the table lists every case where the planned volume differs (single 20 s observation each; a lower planned volume is not a completed-case gain):\n")
    P("| case | planned core entries, full | planned, identity views (A2) | A2 / full | status full / A2 | s full / A2 |\n|---|---|---|---|---|---|")
    for c in cases:
        f0 = full20.get(c); x = a2.get(c)
        if not (f0 and x):
            continue
        pf = ((f0.get("adp") or {}).get("program") or {}).get("core_entries_total"); pa = ((x.get("adp") or {}).get("program") or {}).get("core_entries_total")
        if pf and pa and pf != pa:
            P("| %s | %d | %d | %.1f | %s / %s | %.2f / %.2f |" % (c, pf, pa, pa / pf, f0["status"][:12], x["status"][:12], f0["complete_response_s"], x["complete_response_s"]))
    P("\nOn the four Protein cases the views cut the planned volume 4–56× (none completes at either budget, so the saving is not exercised end to end); on CSP_12 the single observation improves from the A2 time to the full time. These are measured planned-volume effects, not established broad performance wins.\n")
    P("## 12. References: certified cells vs exact / point references\n")
    r0ok = sum(1 for c, x in cont if c in r0cases and x["contained"] == x["coordinates"]); r0n = sum(1 for c, _ in cont if c in r0cases)
    P("Reference classes over the 46 cases: %s. R0 (exact rational) references: %d certified cell(s) (%s) — the exact truth lies inside every published interval in %d of %d (a proof check). R1 / R2 references are POINTS printed to 10 (libDAI) or 6 (official) significant digits, i.e. carrying ≈5e-11 / 5e-7 of their own rounding, while the certified intervals are ≈1e-15 wide: exact containment of such a point is NOT expected and is not a correctness criterion (%d of %d R1/R2-referenced certified cells had every printed point inside; the rest differ by the reference's print rounding). The empirical max coordinate distance between the certified cells' published points and their references is %s — consistent with the references' print precision and far inside the 1/200 contract. Inconsistent certified cells: none.\n" % (json.dumps(S["reference_class_counts"]), r0n, ", ".join(c for c, _ in cont if c in r0cases) or "none", r0ok, r0n, cont_ok - r0ok, len(cont) - r0n, ("%.2e" % max(emp)) if emp else "—"))
    P("## 12b. Accounting reconciliation and measurement disclosures\n")
    P("- **Three totals circulated for the charged wall.** The closeout jobs are themselves charged receipts, so the total moves while the closeout runs: REPORT.md section 8 and the ledger entry were generated from BUDGET_LEDGER.json as it stood at that moment; the packaged BUDGET_LEDGER.json carried the total as of packaging (it cannot contain the receipt of the job that writes it); the final BUDGET_LEDGER.json in the repository adds the package and final-ledger receipts. Rule from now on: BUDGET_LEDGER.json in the repository is authoritative; every prose figure is labelled 'as of <job>'. Five closeout receipts of 0.06–0.07 s are failed launches (a zsh word-splitting error in the first closeout script); they stay in the ledger as charged. Two review-repair test runs were killed together with their charging wrapper and lost their receipts; they are recorded UNRESOLVED with estimates. Consequently `within_ceiling` is stated only for the charged receipts plus those estimates; EXACT compliance with the 28,800 s ceiling is UNPROVED, and the pre-freeze panel exposure below is part of that statement.\n- **Uncharged pre-freeze development executions.** Before the campaign freeze, development dry runs were executed outside the charged ledgers: one 46-case dry run of the full arm at 20 s (recorded cell responses summing to %s s; supervisor walls were not recorded), about twenty probe cells (≈130 s of recorded responses), and the in-process engine probes. They were development work on code that changed before the freeze; they produced no campaign row; they are disclosed here and are NOT part of the 28,800 s accounting, whose rule counts top-level charged receipts.\n- **Undersampled peak memory on short cells.** The supervisor samples the process-tree RSS every 50 ms; %d of the 736 cells have ≤ 3 samples (cells of ≈0.1–0.2 s, mostly baselines), so their peak RSS is a lower bound and must not be compared. Every row records its sample count (`rss_samples`).\n- **The checker is a second interval solver.** It recomputes the authoritative enclosures from the certificate's STRUCTURE (steps, order, views) with its own code; it does not validate the producer's numbers (which are never sent). This is the designed contract (numerics contract: the checker's enclosures govern), and it is why the producer defect F2 (section 12c) could not reach a published answer.\n" % (("%.0f" % DRYRUN_S) if DRYRUN_S else "unknown", UNDERSAMPLED))
    P("## 12c. Review findings of 8 November 2026 and their repair (AMENDMENTS.json amendment_2; reproductions in review_2026-11-08/)\n")
    P("- **F1 publication verifier**: accepted a receipt from the WRONG model (two unary models with opposite probabilities: model 1's receipt and answer named with model 2 → POINT_VERIFIED at error 0.5), accepted a receipt marked REJECTED, and let an empty interval row bypass the coordinate checks. Repaired: the first-invocation checker record now carries the source hashes, variable count and cardinalities; the point verifier requires status INTERVALS_OK, binds the named model by raw + canonical hash, and requires one full, well-formed interval row per variable. All three witnesses now POINT_REJECTED with their specific reason. Saved campaign receipts are complete and source-matching, so no published row is affected.\n- **F2 producer zero-class masking**: when a child view had a zero class along the eliminated variable with unit ratios elsewhere, the producer masked the exact-zero FLAG but not the looked-up VALUE (normalizer 6 instead of 3; P(B) ≈ [1/2, 1/2] instead of [1, 0]). The independent checker computed the correct answer, which governs publication, so no published row is affected (the path is reachable only with the exclude rule off and the sparse format off or abandoned; no saved campaign plan exercised it). Repaired: values are zeroed where the exact-zero mask holds, in `gather_inputs` and again in the product. Controls: the witness model and 400 random zero-bearing models in every non-sparse format.\n- **F3 memory fallback**: dense cores over the resident value cap raised VALUE_CAP instead of switching to lazy evaluation; the lazy memo and the lazy adjoint deltas were not byte-accounted; the lazy evaluator and the reverse flush recursed through the host language (a forced-lazy 400-variable chain raised RecursionError). Repaired: a dense or sparse core that does not fit is served LAZILY (recorded as `downgraded_to_lazy`); the lazy memo is byte-accounted against the value cap (per-node FIFO cap plus a GLOBAL least-recently-used eviction across every lazy node); lazy adjoint deltas are byte-accounted against the adjoint cap and flushed through an explicit QUEUE; the lazy evaluator uses an explicit frame stack whose frames hold their own resolved child values (correctness independent of memo retention); the checker's lazy path is iterative too. Controls: the 400-chain under three configurations incl. the fresh-process cell with checker; tiny-value-cap downgrade; byte accounting. The campaign's cells were produced by the frozen code and are left as they are: every full-arm success ran dense / sparse formats (`lazy_evals = 0`), so the VALUE_CAP stops (BN_12 at 20 s; the four DBNs and the four Grids at 120 s) are stops of the UNFINISHED fallback, not of the intended algorithm — they are not evidence about it.\n- **F4 ablation descriptions** corrected in section 11 and GRAVEYARD.json (A4 disables batching too and still coalesces adjoints; response views retain their planned-volume evidence).\n- Also hardened: step field typing (integers only, with specific rejection reasons); unresolved-frame and unconsumed-adjoint conditions raise typed faults.\n\n**Second review (amendment_3): F5 — evidence was not bound to the caller's task.** Reproduced through the actual publication function on the frozen code AND on the first-repair code (review_2026-11-08/before_91381747/, before_cc6632e2/): the same model with evidence x=1 as the caller's task, a genuine unchanged checker record for evidence x=0 staged in the output directory → `publish()` returned CERTIFIED with the x=0 answer [1,0] (truth for the task [0,1]) and the point verifier returned POINT_VERIFIED, because the repair of F1 bound the receipt to the MODEL only. Repaired: the cell computes the caller's task identity (model + evidence raw and canonical hashes, variable count, cardinalities, query contract = every original variable) from the caller's own files and passes model, evidence and query contract to the checker on the command line; the checker binds the certificate's paths, source hashes and query list to that task and writes the binding into its record; `run_checker` removes any stale record before launch and accepts a record only if its binding equals the caller's task; `publish()` refuses any record that is not an INTERVALS_OK record bound to the caller's task with one full row per variable; the point verifier takes the caller's evidence too and requires the full binding. Control: `test_review2_cross_evidence_substitution_is_refused_at_checking_and_publication` (publication, point verifier, checker CLI and a staged stale record all refuse; the task's own cell certifies [0,1]). Saved campaign cells were produced by the cell's own checker invocation on its own certificate in a fresh directory, so no published row is affected; this is a software defect of the publication boundary.\n\n**Remaining limitations after the two repair passes (documented, not fixed in this closeout):** (a) a sparse node whose complete support is EMPTY raises inside the checker and fails closed (CHECKER_FAULT → cell FAULT, never a certificate); (b) memory accounting is object-count based (reserve-before-allocate over mpfr objects incl. the pending flush queue), externally policed by sampled RSS — not an allocator cap; (c) the repaired lazy fallback (lazy downgrade, byte-accounted memo and adjoints, explicit stacks) is qualified by controls only and has NOT been measured on the panel; the 41 VALUE_CAP invocations (11 distinct cases) of the campaign remain valid records of the FROZEN implementation; rerunning them would be a separate experiment on the repaired implementation.\n\n**Provenance correction (second review).** The first `amendment_2` recorded a `code_hash_to` computed before later edits of the same pass, and the first r2 package's SOURCE_LINEAGE named the pre-repair commit because the package was built before the repair commit; the packaged F2 'before' record used a model on which the frozen code happened to be correct (Z = 3). Corrected: the before-records are regenerated from git worktrees at the exact commits (91381747 frozen; cc6632e2 first repair) with the witness that fails (f(X,B) = [1,0,2,0] → Z 6 vs 3), `amendment_3` records the final code hash, and the r3 package is built AFTER the repair commit so SOURCE_LINEAGE names it.\n")
